    /**
     * run.
     * Invokes C FFI: spikard_app_ep_run
     */
    public void run() {
        try (var callArena = Arena.ofConfined();
             var nativeResources = new ServiceResources()) {

            MemorySegment epAddr = LOOKUP.find("spikard_app_ep_run")
                .or(() -> LOOKUP.find("_spikard_app_ep_run"))
                .orElseThrow();
            FunctionDescriptor epDesc = FunctionDescriptor.of(
                ValueLayout.JAVA_INT,    // return int status
                ValueLayout.JAVA_LONG     // owner: AlefHandle
            );
            MethodHandle epHandle = LINKER.downcallHandle(epAddr, epDesc);
            try (var ownerTransfer = takeOwnerHandle()) {
                int result = (int) epHandle.invokeWithArguments(ownerTransfer.handle()
                );
                ownerTransfer.commit();
                if (result != 0) {
                    throw new IllegalStateException("Service entrypoint failed with status " + result);
                }
            }
        } catch (Throwable e) {
            throw new RuntimeException("Failed to invoke entrypoint", e);
        }
    }
    @Override
    public void close() {
        synchronized (ownerMutationLock) {
        long detached = takeOwnerHandleForClose();
        Throwable failure = null;
        try {
            if (detached != 0) {
                MemorySegment freeAddr = LOOKUP.find("spikard_app_free")
                    .or(() -> LOOKUP.find("_spikard_app_free"))
                    .orElseThrow();
                FunctionDescriptor freeDesc = FunctionDescriptor.ofVoid(ValueLayout.JAVA_LONG);
                MethodHandle freeHandle = LINKER.downcallHandle(freeAddr, freeDesc);
                freeHandle.invokeExact(detached);
            }
        } catch (Throwable e) {
            failure = e;
            throw new RuntimeException("Failed to close service", e);
        } finally {
            try {
                if (markServiceArenaClosed()) arena.close();
            } catch (Throwable cleanupError) {
                if (failure != null) {
                    failure.addSuppressed(cleanupError);
                } else {
                    throw new RuntimeException("Failed to close service arena", cleanupError);
                }
            }
        }
        }
    }
